// Package chainledger implements the on-chain data governance core.
package chainledger

import "sort"

// Dataset is one ingestible on-chain data source with a declared schema version.
type Dataset struct {
	Name          string
	SchemaVersion int
	Rows          int
	Upstreams     []string
}

// Lineage records where a dataset came from, so every derived table can be traced.
type Lineage struct {
	Dataset  string
	Parents  []string
	Children []string
}

// Register links a dataset into the lineage graph.
//
// A dataset is registered under dataset.Name. Registering a name that already
// exists replaces its direct upstreams with the explicitly given parents while
// preserving its existing direct downstreams (and the downstreams' parent links
// back to it). The parent list is deduplicated by first occurrence, and the
// stored upstream order follows the input list. The parents slice is copied, so
// later mutation by the caller cannot affect the graph.
//
// Registration is atomic: if any validation fails (empty name or upstream,
// unknown upstream, self-reference, or a cycle), the graph is left completely
// unchanged. Problems are reported in input order, and error messages name the
// offending dataset/upstream.
func Register(graph map[string]*Lineage, dataset Dataset, parents []string) error {
	if dataset.Name == "" {
		return errInvalid("dataset name is required")
	}

	// Validate and deduplicate parents in a single input-order pass.
	resolved := make([]string, 0, len(parents))
	seen := make(map[string]bool, len(parents))
	for _, parent := range parents {
		if parent == "" {
			return errInvalid("upstream name is required")
		}
		if parent == dataset.Name {
			return errInvalid("dataset cannot be its own upstream: " + parent)
		}
		if _, ok := graph[parent]; !ok {
			return errInvalid("unknown upstream: " + parent)
		}
		if seen[parent] {
			continue
		}
		seen[parent] = true
		resolved = append(resolved, parent)

		// Adding dataset -> parent creates a cycle iff parent can reach
		// dataset by following parent edges. dataset is treated as a
		// terminal target: its own outgoing edges are being replaced and
		// must not participate in the check.
		if reaches(graph, parent, dataset.Name) {
			return errInvalid("cycle detected through upstream: " + parent)
		}
	}

	// All checks passed; apply the replacement.
	node, exists := graph[dataset.Name]
	var oldParents []string
	var oldChildren []string
	if exists {
		oldParents = node.Parents
		oldChildren = node.Children
	}

	// Drop the reverse link on upstreams that are no longer direct parents.
	for _, old := range oldParents {
		if !seen[old] {
			if entry := graph[old]; entry != nil {
				entry.Children = removeName(entry.Children, dataset.Name)
			}
		}
	}
	// Add the reverse link on new upstreams (once); keep the list stable for
	// upstreams that already record this dataset.
	for _, parent := range resolved {
		entry := graph[parent]
		if entry == nil {
			continue
		}
		if !containsName(entry.Children, dataset.Name) {
			entry.Children = append(entry.Children, dataset.Name)
		}
	}

	if !exists {
		graph[dataset.Name] = &Lineage{
			Dataset:  dataset.Name,
			Parents:  resolved,
			Children: nil,
		}
	} else {
		node.Parents = resolved
		// node.Children is intentionally preserved: existing downstreams
		// keep their relative order, and later registrations append.
	}
	return nil
}
```

